class nom(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.page = None
        self.__driver = None
        self._download_dir = None
        self._tmp_download_dir = False
        self._url = None
        self._username = None
        self._password = None
        self._display = None
        self.__debug_dir = None
        self.browser = None
        self.downloader = Downloader()

    @property
    def download_dir(self):
        """ Get download directory path.
        If path was not provided, function returns path to temporary directory,
        which will be removed during logout. """
        return self.get_download_dir()

    def get_download_dir(self):
        """ Function for compatibility with robot framework.  See download_dir property. """
        if self._download_dir is None:
            self._download_dir = tempfile.mkdtemp(suffix="taf_selenium_nms_nom")
        return self._download_dir

    def set_debug_dir(self, debug_dir):
        """
        Set debug directory path.
        :param debug_dir: path to download dir
        """
        self.__debug_dir = os.path.join(debug_dir, "taf_selenium_nms_nom")
        if not os.path.exists(self.__debug_dir):
            os.makedirs(self.__debug_dir)

    @download_dir.setter
    def download_dir(self, download_dir):
        """ Set download directory path.
        Note that this function can be called only before driver initialization.

        :param download_dir: path to download dir
        """
        self.set_debug_dir(download_dir)
        self.set_download_dir(download_dir)

    def set_download_dir(self, download_dir):
        """ Function for compatibility with robot framework. See download_dir property. """
        if self.__driver is None:
            self._download_dir = download_dir
        else:
            raise AttributeError("Download dir must be set before initialization of "
                                 "driver (in most cases before login keyword)")

    @property
    def _debug_dir(self):
        return self.get_debug_dir()

    def get_debug_dir(self):
        """
        Get debug directory path.
        """
        if self.__debug_dir is None:
            self.__debug_dir = tempfile.mkdtemp(prefix="taf_selenium_nms_nom")
        return self.__debug_dir

    @_debug_dir.setter
    def _debug_dir(self, download_dir):
        self.set_download_dir(download_dir)

    @property
    def _driver(self):
        if not self.__driver:
            if self.browser == "Chrome":
                self.__driver = CustomWebDriverChrome(self.download_dir)
            else:
                self.__driver = CustomWebDriverFirefox(self.download_dir)

        return self.__driver

    @catch_interface_exception
    def open_url(self, url, browser="Chrome"):
        """
        Only use it to open url without login.

        :param url: str, link url
        :param browser: str, Default browser will be "Chrome", if user wants it to run via from Firefox
                then then change the browser parameter to "Firefox"

        """
        self.__driver = None
        self.browser = browser
        self._driver.get(url)
        time.sleep(5)

    @catch_interface_exception
    def login(self, url, username="cnms04", password="Qwer_1234", browser="Chrome", timeout=120,
              https_proxy="", is_need_update_driver=True, url_suffix=''):
        """
        Login into nom as Web Element Manager.

        :param url: str, url for nom
        :param username: str, username
        :param password: str, password
        :param browser: str, Default browser will be "Chrome", if user wants it to run via from Firefox
                            then then change the browser parameter to "Firefox"
        :param timeout: int, timeout for the element be available to click
        :param https_proxy: str, the https proxy using for connecting to NOM04, default is empty.
        :param is_need_update_driver: bool, used to judge is set __driver to None.

        """
        if https_proxy != "":
            try:
                cur_proxy = os.environ['HTTPS_PROXY']
                if cur_proxy != https_proxy:
                    os.environ['HTTPS_PROXY'] = https_proxy
            except KeyError:
                os.environ['HTTPS_PROXY'] = https_proxy

        if is_need_update_driver:
            self.__driver = None
        self.browser = browser
        self._driver.get(url)
        self._url = url
        self._username = username
        self._password = password
        self.page = NomLoginPage(self._driver)
        self.page = self.page.login(username, password, int(timeout))
        time.sleep(5)
        if url_suffix:
            new_url = self._driver.current_url + url_suffix
            self._driver.get(new_url)
            self._driver.implicitly_wait(10)

    @catch_interface_exception
    def logout(self, timeout=60):
        """
        Logout from nom web.

        :param timeout: int, timeout for the element be available to click
        """
        self.page = LogoutPage(self._driver)
        self.page = self.page.logout(timeout)

    @catch_interface_exception
    def save_screenshot(self, filename, screenshot_dir=None):
        """
        Keyword for save screen shot, tester can add this keyword after failed test case to provide clues for developer

        :param filename: str, png file name, please keep it unique
        :param screenshot_dir: str or None, screenshot path, user should have permission to read and write this dir
        """
        screenshot_dir = screenshot_dir if screenshot_dir else self._debug_dir
        Debug(self._driver, screenshot_dir).save_screenshot(filename)

