    @catch_interface_exception
    def sw_download_activation(self, dn_name, sw_version, operation_type="download"):
        """
        This keyword is used to download or activation or "download_and_activation" for specified ne.
        :param dn_name: the distinguished name, like 'HQZ-VCU/MRBTS-5221'
        :param sw_version: path of sw version for sw import, it is mandatory when operation type is 'import'
        :param operation_type: can be "download", "activation" or "download_and_activation"
        :return: None
        """
        operation_type = operation_type.upper()
        if operation_type not in ["DOWNLOAD", "ACTIVATION", "DOWNLOAD_AND_ACTIVATION"]:
            raise Exception('not support operation type %s, operation_type should in ["DOWNLOAD", "ACTIVATION", '
                            '"DOWNlOAD_AND_ACTIVATION"]' % operation_type)
        Objects(self._driver).open_page_and_get_instance("Network View"). \
            sw_download_activation(dn_name, sw_version, operation_type.upper())

